#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    int totalOnes = 0;
    for (int x : a) if (x == 1) ++totalOnes;

    int bestGain = -1000000;
    for (int i = 0; i < n; ++i) {
        int gain = 0;
