#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    int ones = 0;
    for (int x : a) if (x == 1) ++ones;

    int bestGain = -1000, current = 0;
    for (int i = 0; i < n; ++i) {
        int val = (a[i] == 0) ? 1 : -1;
        current = max(val, current + val);
        bestGain = max(bestGain, current);
    }

    // Must flip exactly one segment; bestGain could be negative
    cout << ones + bestGain << '\n';
    return 0;
}

